84	const SESSION_WARNING_MS = 60 * 60 * 1000;
85	const SESSION_REFRESH_AHEAD_MS = 5 * 60 * 1000;
86	const SESSION_REFRESH_RETRY_MS = 60 * 1000;
87	const MAX_SESSION_REFRESH_RETRIES = 1;
88	
89	let sessionWarningTimeout: ReturnType<typeof setTimeout> | null = null;
90	let sessionRefreshTimeout: ReturnType<typeof setTimeout> | null = null;
91	let sessionRefreshRetryTimeout: ReturnType<typeof setTimeout> | null = null;
92	let sessionRefreshRetries = 0;
93	
94	function clearSessionTimers() {
95	  if (sessionWarningTimeout) clearTimeout(sessionWarningTimeout);
96	  if (sessionRefreshTimeout) clearTimeout(sessionRefreshTimeout);
97	  if (sessionRefreshRetryTimeout) clearTimeout(sessionRefreshRetryTimeout);
98	  sessionWarningTimeout = null;
99	  sessionRefreshTimeout = null;
100	  sessionRefreshRetryTimeout = null;
101	  sessionRefreshRetries = 0;
102	}
103	
104	function startSessionMaintenance() {
105	  clearSessionTimers();
106	  const token = getAuthToken();
107	  const exp = token ? decodeJwtExp(token) : null;
108	  if (exp === null) return;
109	
110	  const millisecondsUntilExpiry = exp * 1000 - Date.now();
111	  if (millisecondsUntilExpiry <= 0) {
112	    useAuthStore.getState().requireRelogin();
113	    return;
114	  }
115	
116	  const showWarning = () => {
117	    useAuthStore.setState({ sessionExpiringSoon: true });
118	  };
119	  const refresh = () => {
120	    void useAuthStore.getState().refreshSession();
121	  };
122	
123	  if (millisecondsUntilExpiry <= SESSION_WARNING_MS) {
124	    showWarning();
125	  } else {
126	    sessionWarningTimeout = setTimeout(
127	      showWarning,
128	      millisecondsUntilExpiry - SESSION_WARNING_MS,
129	    );
130	  }
131	
132	  sessionRefreshTimeout = setTimeout(
133	    refresh,
134	    Math.max(0, millisecondsUntilExpiry - SESSION_REFRESH_AHEAD_MS),
135	  );
136	}
