138	function applyToken(res: TokenResponse) {
139	  setAuthToken(res.access_token);
140	  useAuthStore.setState({
141	    user: res.user,
142	    features: res.user.features ?? [],
143	    status: "authenticated",
144	    reloginRequired: false,
145	    sessionExpiringSoon: false,
146	    sessionRefreshFailed: false,
147	    totpRequired: false,
148	    totpSessionToken: null,
149	  });
150	  startSessionMaintenance();
151	}
