153	export const useAuthStore = create<AuthState>((set) => ({
154	  status: "loading",
155	  user: null,
156	  features: [],
157	  config: null,
158	  sessionExpiringSoon: false,
159	  sessionRefreshFailed: false,
160	  reloginRequired: false,
161	  pendingInviteToken: null,
162	  pendingPublicTreeId: null,
163	  totpRequired: false,
164	  totpSessionToken: null,
165	  accountOperation: "idle",
166	  accountError: null,
167	
168	  refreshConfig: async () => {
169	    const config = await api.get<AuthConfig>("/auth/config");
170	    set({ config });
171	  },
172	
173	  init: async () => {
174	    // Pick up a token handed back by the Authentik OAuth redirect (#token=...).
175	    const hash = window.location.hash;
176	    if (hash.startsWith("#token=")) {
177	      const token = decodeURIComponent(hash.slice("#token=".length));
178	      setAuthToken(token);
179	      window.history.replaceState(null, "", window.location.pathname);
180	    } else if (hash.startsWith("#invite=")) {
181	      const inviteToken = decodeURIComponent(hash.slice("#invite=".length));
182	      set({ pendingInviteToken: inviteToken });
183	      window.history.replaceState(null, "", window.location.pathname);
184	    } else if (hash.startsWith("#public=")) {
185	      const treeId = decodeURIComponent(hash.slice("#public=".length));
186	      set({ pendingPublicTreeId: treeId });
187	      window.history.replaceState(null, "", window.location.pathname);
188	    }
189	
190	    try {
191	      const config = await api.get<AuthConfig>("/auth/config");
192	      set({ config });
193	    } catch {
194	      // backend unreachable; keep going so the login screen can still render
195	    }
196	
197	    try {
198	      const user = await api.get<User>("/auth/me");
199	      set({
200	        user,
201	        features: user.features ?? [],
202	        status: "authenticated",
203	        reloginRequired: false,
204	        sessionExpiringSoon: false,
205	        sessionRefreshFailed: false,
206	      });
207	      startSessionMaintenance();
208	    } catch {
209	      setAuthToken(null);
210	      set({ user: null, features: [], status: "unauthenticated" });
211	    }
212	  },
213	
214	  login: async (username: string, password: string) => {
215	    const res = await api.post<LoginResponse>("/auth/login", {
216	      username,
217	      password,
218	    });
219	    if (res.totp_required && res.totp_session_token) {
220	      set({ totpRequired: true, totpSessionToken: res.totp_session_token });
221	      return;
222	    }
223	    applyToken(res as TokenResponse);
224	  },
225	
226	  verifyTotp: async (code: string) => {
227	    const { totpSessionToken } = useAuthStore.getState();
228	    if (!totpSessionToken) throw new Error("No TOTP session");
229	    const res = await api.post<TokenResponse>("/auth/totp", {
230	      session_token: totpSessionToken,
231	      code,
232	    });
233	    applyToken(res);
234	  },
235	
236	  cancelTotp: () => {
237	    set({ totpRequired: false, totpSessionToken: null });
238	  },
239	
240	  logout: () => {
241	    clearSessionTimers();
242	    setAuthToken(null);
243	    set({
244	      user: null,
245	      features: [],
246	      status: "unauthenticated",
247	      sessionExpiringSoon: false,
248	      sessionRefreshFailed: false,
249	      reloginRequired: false,
250	      totpRequired: false,
251	      totpSessionToken: null,
252	    });
253	  },
254	
255	  refreshMe: async () => {
256	    const tokenBeforeRefresh = getAuthToken();
257	    const user = await api.get<User>("/auth/me");
258	    if (
259	      getAuthToken() !== tokenBeforeRefresh ||
260	      useAuthStore.getState().status !== "authenticated"
261	    ) {
262	      return;
263	    }
264	    set({ user, features: user.features ?? [] });
265	  },
266	
267	  refreshSession: async () => {
268	    const tokenBeforeRefresh = getAuthToken();
269	    if (!tokenBeforeRefresh) return;
270	
271	    try {
272	      const response = await api.post<TokenResponse>("/auth/refresh");
273	      // A logout or a manual re-login may have completed while this request was
274	      // in flight. Never overwrite that newer session with a stale response.
275	      if (getAuthToken() !== tokenBeforeRefresh) return;
276	      applyToken(response);
277	    } catch {
278	      if (
279	        getAuthToken() !== tokenBeforeRefresh ||
280	        useAuthStore.getState().status !== "authenticated"
281	      ) {
282	        return;
283	      }
284	
285	      set({ sessionExpiringSoon: true, sessionRefreshFailed: true });
286	      const exp = decodeJwtExp(tokenBeforeRefresh);
287	      const millisecondsUntilExpiry = exp ? exp * 1000 - Date.now() : 0;
288	      if (
289	        sessionRefreshRetries < MAX_SESSION_REFRESH_RETRIES &&
290	        millisecondsUntilExpiry > 0
291	      ) {
292	        sessionRefreshRetries += 1;
293	        sessionRefreshRetryTimeout = setTimeout(
294	          () => void useAuthStore.getState().refreshSession(),
295	          Math.min(SESSION_REFRESH_RETRY_MS, millisecondsUntilExpiry),
296	        );
297	      }
298	    }
299	  },
300	
301	  requireRelogin: () => {
302	    const { status, reloginRequired } = useAuthStore.getState();
303	    if (status === "authenticated" && !reloginRequired) {
304	      set({ reloginRequired: true });
305	    }
306	  },
307	
308	  deleteAccount: async (
309	    password: string | null,
310	    confirmUsername: string | null,
311	  ) => {
312	    return runAccountOperation(set, "deleting-account", () =>
313	      AuthService.deleteAccount(password, confirmUsername),
314	    );
315	  },
316	
317	  setupTwoFactor: () =>
318	    runAccountOperation(set, "setting-up-two-factor", () =>
319	      AuthService.setupTwoFactor(),
320	    ),
321	
322	  enableTwoFactor: async (code: string) => {
323	    await runAccountOperation(set, "enabling-two-factor", () =>
324	      AuthService.enableTwoFactor(code),
325	    );
326	    await useAuthStore.getState().refreshMe();
327	  },
328	
329	  disableTwoFactor: async (password: string, code: string) => {
330	    await runAccountOperation(set, "disabling-two-factor", () =>
331	      AuthService.disableTwoFactor(password, code),
332	    );
333	    await useAuthStore.getState().refreshMe();
334	  },
335	
336	  changePassword: (currentPassword: string, newPassword: string) =>
337	    runAccountOperation(set, "changing-password", () =>
338	      AuthService.changePassword(currentPassword, newPassword),
339	    ),
340	
341	  updateProfile: async (firstName: string, lastName: string) => {
342	    const user = await runAccountOperation(set, "saving-profile", () =>
343	      AuthService.updateProfile(firstName, lastName),
344	    );
345	    set({ user, features: user.features ?? [] });
346	  },
347	
348	  uploadProfileImage: async (file: File) => {
349	    const user = await runAccountOperation(set, "uploading-profile-image", () =>
350	      AuthService.uploadProfileImage(file),
351	    );
352	    set({ user, features: user.features ?? [] });
353	  },
354	
355	  removeProfileImage: async () => {
356	    const user = await runAccountOperation(set, "removing-profile-image", () =>
357	      AuthService.removeProfileImage(),
358	    );
359	    set({ user, features: user.features ?? [] });
360	  },
361	
362	  loadOwnedTrees: () => AuthService.getOwnedTrees(),
363	
364	  loadOwnershipTransferTargets: (treeId: string) =>
365	    AuthService.getOwnershipTransferTargets(treeId),
366	
367	  transferTreeOwnership: (treeId: string, username: string) =>
368	    runAccountOperation(set, "deleting-account", () =>
369	      AuthService.transferOwnership(treeId, username),
370	    ),
371	
372	  register: async (
373	    username: string,
374	    password: string,
375	    email: string | null,
376	  ) => {
377	    const res = await api.post<TokenResponse>("/auth/register", {
378	      username,
379	      password,
380	      email,
381	    });
382	    applyToken(res);
383	  },
384	
385	  restoreAccount: async (username: string, password: string) => {
386	    const res = await api.post<TokenResponse>("/auth/restore-account", {
387	      username,
388	      password,
389	    });
390	    applyToken(res);
391	  },
392	
393	  acceptPendingInvite: async () => {
394	    const { pendingInviteToken } = useAuthStore.getState();
395	    if (!pendingInviteToken) return null;
396	    try {
397	      const result = await TreeSharingService.acceptInvite(pendingInviteToken);
398	      set({ pendingInviteToken: null });
399	      return result.tree_id;
400	    } catch {
401	      set({ pendingInviteToken: null });
402	      return null;
403	    }
404	  },
405	}));
406	
407	async function runAccountOperation<T>(
408	  set: (partial: Partial<AuthState>) => void,
409	  operation: Exclude<AccountOperation, "idle">,
410	  action: () => Promise<T>,
411	): Promise<T> {
412	  set({ accountOperation: operation, accountError: null });
413	  try {
414	    return await action();
415	  } catch (error) {
416	    const accountError =
417	      error instanceof Error ? error.message : "Unknown error";
418	    set({ accountError });
419	    throw error;
420	  } finally {
421	    set({ accountOperation: "idle" });
422	  }
423	}
424	
425	/** Reactive hook: is the feature enabled for the current user? */
426	export const useFeature = (feature: FeatureName): boolean =>
427	  useAuthStore((s) => s.features.includes(feature));
428	
429	/** Non-reactive check for store actions and other non-component code. */
430	export const hasFeature = (feature: FeatureName): boolean =>
431	  useAuthStore.getState().features.includes(feature);
432	
433	// Any 401 from the API triggers a relogin dialog instead of a hard logout,
434	// so the user can re-authenticate in-place without losing UI state.
435	// Guard against 401 storms: only transition once; subsequent 401s while the
436	// dialog is already open are no-ops.
437	onUnauthorized(() => {
438	  const { status, reloginRequired } = useAuthStore.getState();
439	  if (status === "authenticated" && !reloginRequired) {
440	    useAuthStore.setState({ reloginRequired: true });
441	  }
442	});
