1	import "./App.css";
2	import { useEffect, useState } from "react";
3	import { useAuthStore } from "@/hooks/useAuthStore";
4	import { resetLegalStoreForSession } from "@/hooks/useLegalStore";
5	import { resetTreeStoreForSession, useTreeStore } from "@/hooks/useTreeStore";
6	import { resetTutorialStoreForSession } from "@/hooks/useTutorialStore";
7	import { resetNotificationStoreForSession } from "@/hooks/useNotificationStore";
8	import { startRealtime, stopRealtime } from "@/services/realtime";
9	import { useAdminViewStore } from "@/hooks/useAdminViewStore";
10	import { useUserSettingsViewStore } from "@/hooks/useUserSettingsViewStore";
11	import { Layout } from "@/components/layout/Layout";
12	import { MainPanel } from "@/components/layout/MainPanel";
13	import { AdminView } from "@/components/admin/AdminView";
14	import { UserSettingsView } from "@/components/settings/UserSettingsView";
15	import { ErrorBoundary } from "@/components/layout/ErrorBoundary";
16	import { UnsavedChangesGuard } from "@/components/layout/UnsavedChangesGuard";
17	import { LoginPage } from "@/components/auth/LoginPage";
18	import { PublicTreeViewer } from "@/components/public/PublicTreeViewer";
19	import { ReloginDialog } from "@/components/auth/ReloginDialog";
20	import { Spinner } from "@/components/ui/spinner";
21	import { Toaster } from "@/components/ui/sonner";
22	import { TooltipProvider } from "@/components/ui/tooltip";
23	
24	export const App = () => {
25	  const status = useAuthStore((s) => s.status);
26	  const init = useAuthStore((s) => s.init);
27	  const user = useAuthStore((s) => s.user);
28	  const userId = user?.id;
29	  const pendingPublicTreeId = useAuthStore((s) => s.pendingPublicTreeId);
30	  const loadTrees = useTreeStore((s) => s.loadTrees);
31	  const openTreeById = useTreeStore((s) => s.openTreeById);
32	  const [treesBootstrapped, setTreesBootstrapped] = useState(false);
33	  const [publicTreeFallback, setPublicTreeFallback] = useState(false);
34	  const adminOpen = useAdminViewStore((s) => s.open);
35	  const settingsOpen = useUserSettingsViewStore((s) => s.open);
36	
37	  useEffect(() => {
38	    void init();
39	  }, [init]);
40	
41	  useEffect(() => {
42	    if (status !== "authenticated" || !userId) {
43	      setTreesBootstrapped(false);
44	      setPublicTreeFallback(false);
45	      resetLegalStoreForSession();
46	      resetTreeStoreForSession();
47	      resetTutorialStoreForSession();
48	      resetNotificationStoreForSession();
49	      stopRealtime();
50	      return;
51	    }
52	
53	    let cancelled = false;
54	    setTreesBootstrapped(false);
55	    setPublicTreeFallback(false);
56	    resetLegalStoreForSession();
57	    resetTreeStoreForSession();
58	    resetTutorialStoreForSession();
59	    resetNotificationStoreForSession();
60	
61	    void (async () => {
62	      try {
63	        // Accept a pending invite (from an #invite= link) before loading trees
64	        // so the newly granted tree appears in the list immediately.
65	        const { acceptPendingInvite } = useAuthStore.getState();
66	        await acceptPendingInvite();
67	
68	        await loadTrees();
69	        startRealtime();
70	
71	        // Public links are also useful to signed-in visitors. Resolve the
72	        // linked tree directly because public trees outside the user's own
73	        // membership list are intentionally absent from GET /trees. A
74	        // password-protected or otherwise inaccessible target falls back to
75	        // the public viewer so it can request the public password.
76	        const { pendingPublicTreeId: targetTreeId } = useAuthStore.getState();
77	        if (targetTreeId) {
78	          try {
79	            await openTreeById(targetTreeId);
80	            useAuthStore.setState({ pendingPublicTreeId: null });
81	            return;
82	          } catch {
83	            if (!cancelled) setPublicTreeFallback(true);
84	            return;
85	          }
86	        }
87	
88	        // Re-open the most recently used tree (or virtual view). The API
89	        // returns both lists sorted by `last_opened`, newest first.
90	        const { selectedTree, trees, virtualViews, selectTree } =
91	          useTreeStore.getState();
92	        const nextTree = trees[0] ?? virtualViews[0];
93	        if (!selectedTree && nextTree) {
94	          await selectTree(nextTree);
95	        }
96	      } finally {
97	        if (!cancelled) {
98	          setTreesBootstrapped(true);
99	        }
100	      }
101	    })();
102	
103	    return () => {
104	      cancelled = true;
105	      stopRealtime();
106	    };
107	  }, [status, userId, loadTrees, openTreeById]);
108	
109	  // The Toaster lives at the root so toasts are visible in every auth state —
110	  // including the login screen, which renders outside the authenticated Layout.
111	  return (
112	    <>
113	      {renderContent()}
114	      <ReloginDialog />
115	      <Toaster position="bottom-center" />
116	    </>
117	  );
118	
119	  function renderContent() {
120	    if (status === "loading") {
121	      return (
122	        <div className="w-screen h-screen flex items-center justify-center">
123	          <Spinner className="size-8" />
124	        </div>
125	      );
126	    }
127	
128	    if (status === "unauthenticated") {
129	      if (pendingPublicTreeId) {
130	        return <PublicTreeViewer treeId={pendingPublicTreeId} />;
131	      }
132	      return <LoginPage />;
133	    }
134	
135	    if (!treesBootstrapped) {
136	      return (
137	        <div className="w-screen h-screen flex items-center justify-center">
138	          <Spinner className="size-8" />
139	        </div>
140	      );
141	    }
142	
143	    if (pendingPublicTreeId && publicTreeFallback) {
144	      return <PublicTreeViewer treeId={pendingPublicTreeId} />;
145	    }
146	
147	    return (
148	      <ErrorBoundary>
149	        <UnsavedChangesGuard />
150	        {adminOpen && user?.is_admin ? (
151	          <TooltipProvider delayDuration={500}>
152	            <AdminView />
153	          </TooltipProvider>
154	        ) : settingsOpen ? (
155	          <UserSettingsView />
156	        ) : (
157	          <Layout>
158	            <MainPanel />
159	          </Layout>
160	        )}
161	      </ErrorBoundary>
162	    );
163	  }
164	};
165

