/** Runs the /auth/me check and applies its result to the store. Only a 401
 *  (a definitive credential rejection — see `get_current_user`) clears the
 *  stored token; network errors, timeouts, and 5xx responses are transient
 *  and leave the token in place so a retry or reload can resume the session. */
async function checkAuthSession(): Promise<void> {
  try {
    const user = await api.get<User>("/auth/me");
    useAuthStore.setState({
      user,
      features: user.features ?? [],
      status: "authenticated",
      reloginRequired: false,
      sessionExpiringSoon: false,
