    return () => {
      cancelled = true;
      stopRealtime();
    };
  }, [status, userId, loadTrees, openTreeById]);

  // The Toaster lives at the root so toasts are visible in every auth state —
  // including the login screen, which renders outside the authenticated Layout.
  return (
    <>
      {renderContent()}
      <ReloginDialog />
      <Toaster position="bottom-center" />
    </>
  );

  function renderContent() {
    if (status === "loading") {
      return (
        <div className="w-screen h-screen flex items-center justify-center">
          <Spinner className="size-8" />
        </div>
      );
    }

    if (status === "unauthenticated") {
      if (pendingPublicTreeId) {
        return <PublicTreeViewer treeId={pendingPublicTreeId} />;
      }
      return <LoginPage />;
    }

    if (!treesBootstrapped) {
      return (
        <div className="w-screen h-screen flex items-center justify-center">
          <Spinner className="size-8" />
        </div>
      );
    }

    if (pendingPublicTreeId && publicTreeFallback) {
      return <PublicTreeViewer treeId={pendingPublicTreeId} />;
    }

    return (
      <ErrorBoundary>
        <UnsavedChangesGuard />
        {adminOpen && user?.is_admin ? (
          <TooltipProvider delayDuration={500}>
            <AdminView />
          </TooltipProvider>
        ) : settingsOpen ? (
          <UserSettingsView />
        ) : (
          <Layout>
            <MainPanel />
          </Layout>
        )}
      </ErrorBoundary>
    );
  }
};

